import Foundation

extension Deck {
    /// The Suit of Pentacles — earth, work, money, body, and the material world. Ids 64...77.
    static let pentacles: [TarotCard] = [
        TarotCard(id: 64, name: "Ace of Pentacles", arcana: .minor, suit: .pentacles, number: 1, element: .earth,
                  keywords: ["opportunity", "prosperity", "new venture", "manifestation"],
                  upright: "A seed of material opportunity — a new job, venture, or resource. Plant it well and tangible prosperity can grow.",
                  reversed: "A missed opportunity or shaky foundations. Re-examine the plan before committing real resources."),
        TarotCard(id: 65, name: "Two of Pentacles", arcana: .minor, suit: .pentacles, number: 2, element: .earth,
                  keywords: ["balance", "adaptability", "juggling", "priorities"],
                  upright: "Skillfully juggling priorities and adapting to change. Stay flexible and keep your commitments in balance.",
                  reversed: "Overwhelmed and dropping the ball. Simplify — you're trying to hold too much at once."),
        TarotCard(id: 66, name: "Three of Pentacles", arcana: .minor, suit: .pentacles, number: 3, element: .earth,
                  keywords: ["teamwork", "collaboration", "skill", "craftsmanship"],
                  upright: "Collaboration where each person's skill builds something greater. Value teamwork and take pride in your craft.",
                  reversed: "Disorganized teamwork or unrecognized effort. Clarify roles and make sure good work is seen."),
        TarotCard(id: 67, name: "Four of Pentacles", arcana: .minor, suit: .pentacles, number: 4, element: .earth,
                  keywords: ["security", "control", "saving", "holding on"],
                  upright: "Holding tightly to what you have for security and stability. Some caution is wise; just don't let it become a cage.",
                  reversed: "Loosening a tight grip, or fear of loss easing. Generosity and flow return when you stop clutching."),
        TarotCard(id: 68, name: "Five of Pentacles", arcana: .minor, suit: .pentacles, number: 5, element: .earth,
                  keywords: ["hardship", "insecurity", "isolation", "worry"],
                  upright: "A spell of material hardship or feeling left out in the cold. Help is nearer than it looks — don't pass the lit door by.",
                  reversed: "Recovery from hardship and support arriving. The lean season turns toward stability again."),
        TarotCard(id: 69, name: "Six of Pentacles", arcana: .minor, suit: .pentacles, number: 6, element: .earth,
                  keywords: ["generosity", "giving and receiving", "balance", "charity"],
                  upright: "A fair flow of giving and receiving; generosity returns to you. Share what you have and accept help graciously.",
                  reversed: "Strings attached, debt, or one-sided giving. Check whether the exchange is truly fair to both sides."),
        TarotCard(id: 70, name: "Seven of Pentacles", arcana: .minor, suit: .pentacles, number: 7, element: .earth,
                  keywords: ["patience", "long-term view", "investment", "assessment"],
                  upright: "Pausing to assess a long-term investment that's slowly bearing fruit. Patience and steady effort will pay off.",
                  reversed: "Impatience or doubting the payoff. Decide whether to keep tending the field or redirect your effort."),
        TarotCard(id: 71, name: "Eight of Pentacles", arcana: .minor, suit: .pentacles, number: 8, element: .earth,
                  keywords: ["mastery", "diligence", "skill-building", "dedication"],
                  upright: "Diligent, focused work that hones your craft toward mastery. Show up daily — repetition is building real skill.",
                  reversed: "Cutting corners or losing motivation. Reconnect with why the work matters before quality slips."),
        TarotCard(id: 72, name: "Nine of Pentacles", arcana: .minor, suit: .pentacles, number: 9, element: .earth,
                  keywords: ["abundance", "self-sufficiency", "luxury", "independence"],
                  upright: "Refined self-sufficiency and well-earned abundance enjoyed alone. Savor the fruits of your discipline and independence.",
                  reversed: "Overworking for status, or financial dependence. Reclaim the freedom and self-worth that money alone can't buy."),
        TarotCard(id: 73, name: "Ten of Pentacles", arcana: .minor, suit: .pentacles, number: 10, element: .earth,
                  keywords: ["legacy", "wealth", "family", "lasting stability"],
                  upright: "Lasting wealth, family legacy, and long-term security. Build something that endures and supports those after you.",
                  reversed: "Financial strain or family tension over resources. Tend the foundation before the legacy can stand."),
        TarotCard(id: 74, name: "Page of Pentacles", arcana: .minor, suit: .pentacles, number: 11, element: .earth,
                  keywords: ["ambition", "study", "new opportunity", "diligence"],
                  upright: "A studious beginner planting seeds of a practical goal. Commit to learning and lay groundwork with patience.",
                  reversed: "Procrastination or impractical plans. Turn the daydream into a concrete first step."),
        TarotCard(id: 75, name: "Knight of Pentacles", arcana: .minor, suit: .pentacles, number: 12, element: .earth,
                  keywords: ["reliability", "diligence", "routine", "persistence"],
                  upright: "Steady, reliable progress through methodical effort and routine. Slow and dependable wins this race.",
                  reversed: "Stagnation, boredom, or being overly rigid. Add a little flexibility so steadiness doesn't become a rut."),
        TarotCard(id: 76, name: "Queen of Pentacles", arcana: .minor, suit: .pentacles, number: 13, element: .earth,
                  keywords: ["nurturing", "practicality", "resourcefulness", "abundance"],
                  upright: "Warm, practical nurturing that creates abundance and comfort. Care for yourself and others through grounded action.",
                  reversed: "Neglecting self-care or work-life balance. Replenish your own resources before tending everyone else's."),
        TarotCard(id: 77, name: "King of Pentacles", arcana: .minor, suit: .pentacles, number: 14, element: .earth,
                  keywords: ["wealth", "stability", "leadership", "abundance"],
                  upright: "Established prosperity and grounded, generous leadership. Build security and share it with steady wisdom.",
                  reversed: "Greed, materialism, or controlling through money. Remember that worth is more than wealth.")
    ]
}
